  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  min-height: 50px;
  justify-content: center;
  align-items: center;
  gap: 12px;
  padding: 12px 20px;
  border: 1px solid var(--line-strong, rgb(255 255 255 / 18%));
  border-radius: 5px;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
