}
.ds-primary {
  background: var(--crimson, #ef3340);
  border-color: var(--crimson, #ef3340);
  color: #fff;
  box-shadow: 0 16px 40px rgb(239 51 64 / 20%);
}
.ds-secondary {
  background: rgb(255 255 255 / 4.5%);
}
.ds-text {
  padding-inline: 0;
  border-color: transparent;
  justify-content: flex-start;
}
