    color: var(--crimson-hover, #ff4a56);
  }
  .ds-primary:hover svg, .ds-secondary:hover svg, .ds-text:hover svg {
    transform: translateX(4px);
  }

}
.ds-primary:active, .ds-secondary:active, .ds-text:active {
  transform: translateY(1px);
  border-color: var(--crimson, #ef3340);
}
.ds-primary:active {
  background: var(--crimson-dark, #a50f28);
}
@media (max-width: 767px) {
  .ds-primary {
    width: 100%;
  }

}
