.ds-form { display: grid; gap: 20px; margin-top: 32px; }
.ds-controls { display: grid; gap: 20px; min-width: 0; margin: 0; padding: 0; border: 0; }
.ds-visuallyHidden { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.ds-status { font-size: 14px; color: var(--text-label, #d9dde3); overflow-wrap: anywhere; }
.ds-status:empty { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.ds-field { display: grid; gap: 8px; }
.ds-field label { color: var(--text-label, #d9dde3); font-size: 14px; font-weight: 700; }
.ds-field input, .ds-field select, .ds-field textarea { width: 100%; min-height: 48px; padding: 12px; border: 1px solid var(--line-strong, rgb(255 255 255 / 18%)); border-radius: 5px; color: var(--foreground, #f4f6f8); background: var(--surface, #0e141d); font: inherit; }
.ds-field textarea { min-height: 148px; resize: vertical; }
.ds-field input:focus, .ds-field select:focus, .ds-field textarea:focus { border-color: var(--crimson, #ef3340); outline: 3px solid rgb(239 51 64 / 25%); outline-offset: 2px; }
.ds-error { color: var(--crimson-hover, #ff4a56); font-size: 14px; }
.ds-form button { min-height: 50px; padding: 12px 20px; justify-self: start; border: 1px solid var(--crimson, #ef3340); border-radius: 5px; background: var(--crimson, #ef3340); color: #fff; font: inherit; font-weight: 700; cursor: pointer; }

.ds-field input::placeholder, .ds-field textarea::placeholder { color: var(--text-secondary, #9aa5b3); opacity: 1; }
.ds-field input, .ds-field select, .ds-field textarea { caret-color: var(--crimson, #ef3340); }
.ds-help { font-size: 14px; }
.ds-help a { color: var(--foreground, #f4f6f8); text-decoration: underline; text-underline-offset: 3px; }
.ds-form button { background: var(--crimson-dark, #a50f28); transition: background 180ms var(--ease, cubic-bezier(.2, .75, .2, 1)), transform 180ms var(--ease, cubic-bezier(.2, .75, .2, 1)); }
.ds-form button:hover:not(:disabled) { background: var(--background, #07090d); }
.ds-form button:active:not(:disabled) { transform: translateY(1px); }
.ds-form button:disabled { cursor: default; background: var(--surface, #0e141d); border-color: var(--line-strong, rgb(255 255 255 / 18%)); color: var(--text-label, #d9dde3); }
.ds-controls:disabled input, .ds-controls:disabled select, .ds-controls:disabled textarea { opacity: 1; color: var(--text-secondary, #9aa5b3); cursor: default; }
@media (prefers-reduced-motion: reduce) { .ds-form button { transition: none; transform: none; } }
